import { NextResponse } from "next/server";
import { requireWorkspace } from "@/lib/auth";
import { ChatGPTError, finishSignIn } from "@/lib/ai/chatgpt";
import { getEnv } from "@/lib/env";
import { connectionReturn } from "@/lib/desktop-bridge";

// ChatGPT redirects here (on 127.0.0.1, as OpenAI requires) after the owner signs in.
export async function GET(request: Request) {
  const back = (result: string) => connectionReturn(getEnv().NEXT_PUBLIC_APP_URL, `/settings?chatgpt=${encodeURIComponent(result)}#ai-access`);
  try { await requireWorkspace(); } catch { return NextResponse.redirect(new URL("/setup", request.url), 303); }
  try {
    await finishSignIn(new URL(request.url).searchParams);
    return back("connected");
  } catch (error) {
    return back(error instanceof ChatGPTError ? error.message : "ChatGPT sign-in failed. Try again.");
  }
}
import { requireWorkspace } from "@/lib/auth";
import { aiConfigured, voiceApiKey } from "@/lib/ai/configured";

/** Whether chat and voice can run, so the UI can guide the owner to Settings instead of failing. */
export async function GET() {
  try { await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const [ai, voice] = await Promise.all([aiConfigured(), voiceApiKey()]);
  return Response.json({ ai, voice: Boolean(voice) }, { headers: { "Cache-Control": "no-store" } });
}
import { serviceKey } from "@/lib/service-keys";
import { chatgptStatus } from "./chatgpt";

/** Whether any AI is set up: a ChatGPT sign-in or an API key. */
export async function aiConfigured() {
  const [openai, openrouter] = await Promise.all([serviceKey("openai_api_key"), serviceKey("openrouter_api_key")]);
  return Boolean(openai || openrouter) || (await chatgptStatus()).signedIn;
}

/** Voice calls, dictation and voice samples need an OpenAI API key: plan usage and OpenRouter have no realtime audio. */
export const voiceApiKey = REDACTED => serviceKey("openai_api_key");
"use client";

import { useEffect, useState } from "react";

export type AiAccessState = { ai: boolean; voice: boolean };

/** What AI the owner has set up, or null while loading (or when it can't be read, so nothing is blocked). */
export function useAiAccess() {
  const [access, setAccess] = useState<AiAccessState | null>(null);
  useEffect(() => {
    const controller = new AbortController();
    fetch("/api/ai/status", { cache: "no-store", signal: controller.signal })
      .then(response => response.ok ? response.json() : null)
      .then(body => { if (body && typeof body.ai === "boolean" && typeof body.voice === "boolean") setAccess({ ai: body.ai, voice: body.voice }); })
      .catch(() => undefined);
    return () => controller.abort();
  }, []);
  return access;
}
// Shown wherever voice is offered without an OpenAI API key; safe to import in the browser.
