const require = createRequire("C:/Users/mgsuk/.t3/worktrees/Moneo/t3-75d3241e-3f4de21a79278a18/package.json");
const { chromium } = require("@playwright/test");
const out = "C:/Users/mgsuk/AppData/Local/Temp/claude/9dabb461ba23d33d/7000e3c8-ae48-4316-9527-82228ad8caea/scratchpad/shots";
const base = "http://localhost:3101";
const step = process.argv[2] ?? "settings";

const browser = await chromium.launch();
const shoot = async (name, options) => {
  const context = await browser.newContext(options);
  const page = await context.newPage();
  await page.goto(`${base}/settings#ai-access`, { timeout: 120_000 });
  const section = page.locator("#ai-access");
  await section.waitFor({ timeout: 120_000 });
  await section.screenshot({ path: `${out}/${name}.png` });
  await context.close();
};

if (step === "settings") {
  await shoot("settings-light", { colorScheme: "light", viewport: { width: 1280, height: 900 } });
  await shoot("settings-dark", { colorScheme: "dark", viewport: { width: 1280, height: 900 } });
  await shoot("settings-mobile", { colorScheme: "light", viewport: { width: 390, height: 844 } });
}

if (step === "chat") {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto(`${base}/settings#ai-access`, { timeout: 120_000 });
  const use = page.getByRole("button", { name: "Use Claude plan" });
  if (await use.count()) { await use.click(); await page.waitForLoadState("networkidle"); }
  console.log("in use:", await page.locator("#ai-access").getByText("· in use").allTextContents());
  await page.locator("#ai-access").screenshot({ path: `${out}/settings-claude-in-use.png` });
  const chatUsed = page.waitForResponse(response => new URL(response.url()).pathname === "/api/chat" && response.request().method() === "POST", { timeout: 180_000 });
  await page.goto(`${base}/ai?conversation=new`, { timeout: 120_000 });
  const started = Date.now();
  await page.getByLabel(/ask about your finances/i).fill("Which accounts do I have, and what is my net worth today? Use your tools.");
  await page.getByRole("button", { name: "Send" }).click();
  const response = await chatUsed;
  console.log("chat status", response.status(), "after", Date.now() - started, "ms");
  await page.waitForTimeout(3000);
  await page.screenshot({ path: `${out}/chat-claude.png`, fullPage: false });
  console.log("body text:", (await page.locator("main").innerText()).slice(0, 1500));
}
await browser.close();

